const connectorById = (id) => CONNECTORS.find(c => c.id === id);
/* Platforms that run on the user's own hardware (category:'local') — Pricing.cost() zero-prices rows
 * whose OWN platform is in this set. CONNECTORS is static at runtime, so a const computed once here is fine. */
const LOCAL_PLATFORMS = new Set(CONNECTORS.filter(c => c.category === 'local').map(c => c.platform));
/* Provider ids that mean "inference ran on the user's own hardware" (no API bill). Coding-tool logs keep their
 * own platform (Continue.dev / Cline / Roo / Aider / Codex) but name the backend — Continue's event.provider, Cline's
 * model_usage[].model_provider_id, Aider's LiteLLM prefix (ollama_chat/, ollama/, lm_studio/…), Codex's
 * session_meta.model_provider (built-in OSS ids 'ollama' / 'lmstudio', 'oss' in older builds). The parser sets
 * local:1 on the row and Pricing.cost() zero-prices it. Matched on the PROVIDER field only — never on the model name. */
const LOCAL_PROVIDER_IDS = new Set(['ollama', 'ollama_chat', 'lmstudio', 'lm_studio', 'llama.cpp', 'llamacpp', 'llamafile', 'localai', 'jan', 'gpt4all', 'msty', 'vllm', 'text-generation-webui', 'text-gen-webui', 'koboldcpp']);
const isLocalProvider = (p) => p != null && LOCAL_PROVIDER_IDS.has(String(p).trim().toLowerCase());
/* Hub groups (spec order). Within a group: connected → attention → disconnected, then registry order. */
const HUB_GROUPS = [
  { id: 'coding', label: 'Coding tools' },
  { id: 'chat',   label: 'Chat apps' },
  { id: 'local',  label: 'Local runners' },
  { id: 'api',    label: 'API vendors' },
  { id: 'cloud',  label: 'Cloud' },
];
/* Data-quality badge copy (honesty rule: quality first). */
const QUALITY_LABEL = { exact: 'exact', estimated: 'estimated', validate: 'validate-only', none: 'no data' };
/* Key-driver extra fields: `secret: true` (or type 'password') = masked AND stored only under the key's Remember rule, never for sessionOnly cards. */
const fieldIsSecret = (f) => !!(f && (f.secret || f.type === 'password'));

